    # The encoding translates each nibble using (int_val + offset) -> digit
    decoded = ''
    for i in range(0, len(hextxt), 7):
        nibval = int(hexxtxt[i:i+7])
        nibble = nibval - offset
        if not (0<=nibble<16):
            # invalid
            decoded += '.'
        else:
            decoded += format(nibble, 'x')
    return decoded

